import requests
import json
import pandas as pd
import seaborn as sns
HEADERS = {
    'accept': 'application/json'
}
def task_func(url, parameters):
    if not url or not isinstance(url, str):
        raise Exception("Invalid URL provided.")

    try:
        response = requests.get(url, params=parameters, headers=HEADERS, verify=False)
        response.raise_for_status()
        data = response.json()
    except Exception as e:
        raise Exception(f"Failed to retrieve data from URL: {e}")

    if not data or not isinstance(data, list) or len(data) == 0:
        raise Exception("Empty or invalid data received from API.")

    try:
        df = pd.DataFrame(data)
        if df.empty:
            raise Exception("DataFrame is empty after conversion.")

        numeric_df = df.select_dtypes(include=['number'])

        if numeric_df.empty:
            raise Exception("No numerical columns found for correlation analysis.")

        corr_matrix = numeric_df.corr()

        ax = sns.heatmap(corr_matrix, annot=True, cmap='coolwarm', linewidths=.5)

        return df, ax
    except Exception as e:
        raise Exception(f"Error processing data or generating heatmap: {e}")
